def lookup(items: list[dict[str, str]], key: str) -> dict[str, str] | None:
    for item in items:
        if item.get("id") == key:
            return item
    return None

files.classifier.py:
def classify(value):
    if value is None:
        return "missing"
    if isinstance(value, bool):
        return "boolean"
    if isinstance(value, int):
        if value < 0:
            return "negative"
        if value == 0:
            return "zero"
        return "positive"
    if isinstance(value, str):
        if not value:
            return "empty"
        return "text"
    raise TypeError("unsupported value")

